"""Writes paper/rare.tex (rare-supertype paragraph) from rare/*.json, so every number is copied programmatically."""
import os, json
V2 = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); RD = os.path.join(V2, "results", "rare")
R = json.load(open(os.path.join(RD, "rare_results.json"))); Ds = json.load(open(os.path.join(RD, "rare_descriptive.json")))
Sm = json.load(open(os.path.join(RD, "rare_sim_summary.json"))); meta = json.load(open(os.path.join(RD, "rare_prep_meta.json")))
f2 = lambda x: f"{x:.2f}"; f3 = lambda x: f"{x:.3f}"; n = lambda x: f"{int(x):,}".replace(",", "{,}")
s1, s2 = R["S1"], R["S2"]; q1, q2 = s1["Q1"], s1["Q2"]; g = Sm["sim_S1"]
gate = g["LCP"]["fdp"][0] > 0.05 + 2 * g["LCP"]["fdp"][1]
s2sim = Sm.get("sim_S2")
txt = rf"""\paragraph{{A naturally rare supertype (analysis plan frozen before the run).}} To test the setting where the leak should matter, we analysed SEA-AD Micro-PVM\_1 nuclei, which are rare in every donor: {s1['D']} donors with at least four nuclei, median {int(s1['n_median'])} per donor ({n(s1['cells'])} nuclei), no down-sampling. The decision rules were written and committed before any statistic was computed (repository \texttt{{prereg/RARE\_PREREG.md}}). As an independent reference we used the same donors' Micro-PVM\_2 nuclei (disjoint cells, median {int(meta['REF']['n_median'])} per donor). \emph{{Calibration gate.}} In a simulation with these donors' exact cell numbers, LCP's FDR was {f3(g['LCP']['fdp'][0])}\,({f3(g['LCP']['fdp'][1])}), {'above' if gate else 'within'} the pre-specified tolerance, and its type-I error for strong within-only pairs {f3(g['LCP']['ss'][0])}; pseudobulk's FDR was {f3(g['PB']['fdp'][0])} and its within-only type-I error {f3(g['PB']['ss'][0])}. {'By our rule the real-data comparison below is therefore descriptive: LCP is much less affected than pseudobulk at these cell numbers but is not calibrated.' if gate else ''} \emph{{Divergence.}} Pseudobulk called {n(s1['n_PB'])} pairs and LCP {n(s1['n_LCP'])}; {n(q1['n_PBonly'])} pseudobulk calls ({f2(q1['n_PBonly']/s1['n_PB'])}) were not LCP calls. Their median leak share was {f2(q1['leakshare_med_PBonly'])}, against {f2(q1['leakshare_med_both'])} for pairs called by both, and they replicated as same-sign LCP calls in the deep Micro-PVM\_2 reference less often ({f2(q1['repl_ref_PBonly'])}) than shared calls ({f2(q1['repl_ref_both'])}) or LCP-only calls ({f2(q1['repl_ref_LCPonly'])}). \emph{{Q1 (are they within-donor programs?): {q1['decision']}.}} In the independent Micro-PVM\_2 cells their median absolute within-donor correlation ({f3(q1['med_absrw_PBonly'])}) was higher than that of LCP-only pairs ({f3(q1['med_absrw_LCPonly'])}) but lower than that of shared calls ({f3(q1['med_absrw_both'])}), so the pre-specified criterion failed. In Lee 2026 donors they replicated as often as LCP-only pairs ({f2(Ds['S1']['PB-only']['repl_lee'])} vs {f2(Ds['S1']['LCP-only']['repl_lee'])}). \emph{{Q2 (does removing them change a downstream result?): {q2['decision']}.}} Removing the pseudobulk-only pairs replaced {len(q2['hubs_dropped'])} of the top-20 hub genes of the pseudobulk network (Jaccard {f2(q2['J'])}; random removal of the same number of edges: median {f2(q2['J_random_median'])}, 5th percentile {f2(q2['J_random_p05'])}). In the more abundant Micro-PVM\_3 supertype ({s2['D']} donors, median {int(s2['n_median'])} nuclei) Q1 was {s2['Q1']['decision']} and Q2 {s2['Q2']['decision']} (Jaccard {f2(s2['Q2']['J'])}, random 5th percentile {f2(s2['Q2']['J_random_p05'])}){', and the same simulation gate gave LCP FDR ' + f3(s2sim['LCP']['fdp'][0]) + ' (' + f3(s2sim['LCP']['fdp'][1]) + ') and pseudobulk ' + f3(s2sim['PB']['fdp'][0]) + ' (not in the plan)' if s2sim else ''}. So with naturally few cells the two methods give materially different networks, and the matched simulation says pseudobulk's version is far less reliable; but we could not show directly on real data that the discarded pairs are within-donor programs.
"""
open(os.path.join(V2, "paper", "rare.tex"), "w").write(txt); print(txt)
